        unitOfWork = module.newUnitOfWork();
        charles = unitOfWork.get(charles);
        daniel = unitOfWork.get(daniel);
        Assert.assertTrue(charles.isFriend(daniel));
        unitOfWork.complete();
    } finally {
        unitOfWork.discard();
    }
}

