    // -> Active
    //
    // Module.beforePassivation
    "Beta.beforePassivation", "Alpha.beforePassivation", // Layer.beforePassivation
    "Beta.beforePassivation", "Alpha.beforePassivation", // Application.beforePassivation
    "Beta.beforePassivation", "Alpha.beforePassivation", //
    // -> Passivation
    //
    // Module.afterPassivation
