/**
 * Tests that stack trace is cleaned up on an application exception.
 */
@Test
public void cleanStackTraceOnApplicationException() {
    // Don't run the satisfiedBy if compacttrace is set to anything else but proxy
    String compactTracePropertyValue = System.getProperty("qi4j.compacttrace");
    if (compactTracePropertyValue != null && !"proxy".equals(compactTracePropertyValue)) {
        return;
    }
    TestComposite composite = module.newTransient(TestComposite.class);
    try {
        composite.doStuff();
    } catch (RuntimeException e) {
        StringWriter actualTrace = new StringWriter();
        e.printStackTrace(new PrintWriter(actualTrace));
        String separator = System.getProperty("line.separator");
        String correctTrace = "java.lang.RuntimeException" + separator + "\tat org.qi4j.test.composite.CleanStackTraceTest$DoStuffMixin.doStuff(CleanStackTraceTest.java:91)" + separator + "\tat org.qi4j.test.composite.CleanStackTraceTest$TestComposite.doStuff(Unknown Source)" + separator + "\tat org.qi4j.test.composite.CleanStackTraceTest.cleanStackTraceOnApplicationException(CleanStackTraceTest.java:60)";
        String actual = actualTrace.toString();
        actual = actual.substring(0, correctTrace.length());
        assertEquals(correctTrace, actual);
    }
}

@Test
public void givenEmptyJSONManyAssociationStateWhenAddingTwoRefsAtZeroIndexExpectCorrectOrder() throws JSONException {
    // Fake JSONManyAssociationState
    JSONObject state = new JSONObject();
    state.put(JSONEntityState.JSON_KEY_PROPERTIES, new JSONObject());
    state.put(JSONEntityState.JSON_KEY_ASSOCIATIONS, new JSONObject());
    state.put(JSONEntityState.JSON_KEY_MANYASSOCIATIONS, new JSONObject());
    JSONEntityState entityState = new JSONEntityState(null, null, "0", System.currentTimeMillis(), EntityReference.parseEntityReference("123"), EntityStatus.NEW, null, state);
    JSONManyAssociationState jsonState = new JSONManyAssociationState(entityState, new JSONArray());
