@Test
public void whenRequestQi4jValueExpectCorrectResult() throws Exception {
    // Start server;
    DividendsMain.main(new String[0]);
    HttpClient httpclient = new DefaultHttpClient();
    HttpPost httpPost = new HttpPost("http://localhost:9300/ProjectedDividendsService");
    httpPost.setHeader("SOAPAction", "\"DSDataRequest\"");
    httpPost.setHeader("Content-Type", "text/xml;charset=UTF-8");
    HttpEntity data = new StringEntity("<soapenv:Envelope xmlns:soapenv=\"http://schemas.xmlsoap.org/soap/envelope/\" " + "xmlns:divs=\"http://divs.cxf.library.qi4j.org/\" " + "xmlns:cxf=\"http://cxf.library.qi4j.org\">\n" + "   <soapenv:Header/>\n" + "   <soapenv:Body>\n" + "      <divs:DSData>\n" + "         <!--Optional:-->\n" + "         <divs:RequestType>?</divs:RequestType>\n" + "         <!--Optional:-->\n" + "         <divs:DataService>?</divs:DataService>\n" + "         <!--Optional:-->\n" + "         <divs:Subscription>\n" + "            <!--Optional:-->\n" + "            <cxf:key>?</cxf:key>\n" + "         </divs:Subscription>\n" + "      </divs:DSData>\n" + "   </soapenv:Body>\n" + "</soapenv:Envelope>");
    httpPost.setEntity(data);
    HttpResponse response = httpclient.execute(httpPost);
    HttpEntity entity = response.getEntity();
    String result = "";
    if (entity != null) {
        InputStream instream = entity.getContent();
        InputStreamReader isr = new InputStreamReader(instream);
        BufferedReader br = new BufferedReader(isr);
        String line = br.readLine();
        while (line != null) {
            result = result + line;
            line = br.readLine();
        }
    }
    XMLAssert.assertXMLEqual(EXPECTED, result);
}

